def hook(ctx, nb):
    if ctx.action.tool == 'click_action' and ctx.action.value_normalized == 'buy now':
        if ctx.predicates.required_options_unselected:
            reqs = []
            if ctx.task.required_color:
                reqs.append('color: ' + ctx.task.required_color)
            if ctx.task.required_size:
                reqs.append('size: ' + ctx.task.required_size)
            if ctx.task.required_material:
                reqs.append('material: ' + ctx.task.required_material)
            if reqs:
                msg = 'You must select the required options before buying: ' + ', '.join(reqs) + '.'
            else:
                msg = 'You must select the required options before buying.'
            return {'kind': 'block_and_prompt', 'message': msg}
    return None
